#include "studio.hpp"
#include <QDialog>
#include <QDir>
#include <QPointer>
#include <QDialogButtonBox>
#include <QFormLayout>
#include <QVBoxLayout>
#include <QPushButton>
#include <QSpinBox>
#include <QComboBox>
