void StudioWindow::createBenchmark(){
 if(bridge.busy())return;QDialog dialog(this);dialog.setObjectName("benchmarkDialog");dialog.setWindowTitle(tr("완결 샘플 제작"));auto box=new QVBoxLayout(&dialog);auto form=new QFormLayout;box->addLayout(form);auto kind=new QComboBox;kind->setObjectName("benchmarkKind");for(auto pair:QList<QPair<QString,QString>>{{"schedule",tr("일정형")},{"free",tr("자유 행동형")},{"relationship",tr("관계형")},{"adventure",tr("모험형")},{"roster",tr("다인 운영형")},{"pet",tr("펫형")}})kind->addItem(pair.second,pair.first);auto title=new QLineEdit(tr("나의 작은 육성 이야기"));title->setObjectName("benchmarkTitle");auto root=new QLineEdit;root->setObjectName("benchmarkRoot");root->setPlaceholderText(tr("새 프로젝트의 절대 경로 · 기존 폴더 덮어쓰기 금지"));auto budget=new QSpinBox;budget->setObjectName("benchmarkBudget");budget->setRange(0,999);budget->setValue(30);form->addRow(tr("유형"),kind);form->addRow(tr("게임 제목"),title);form->addRow(tr("새 폴더"),root);form->addRow(tr("초기 자금"),budget);auto hint=new QLabel(tr("한 달 두 기간, 목표 달성/미달성 결말을 가진 일반 프로젝트를 만듭니다. 생성 후 규칙·화면·인물은 기존 제작 도구에서 수정할 수 있습니다."));hint->setWordWrap(true);box->addWidget(hint);auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);box->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{if(QDir::isAbsolutePath(root->text())&&!title->text().trimmed().isEmpty())dialog.accept();else hint->setText(tr("제목과 새 프로젝트의 절대 경로를 입력하세요."));});connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.resize(650,300);if(dialog.exec()!=QDialog::Accepted)return;
 request("createBenchmark",{{"kind",kind->currentData().toString()},{"title",title->text()},{"root",root->text()},{"budget",budget->value()}});
}

void StudioWindow::runAssuranceDialog(){
 if(bridge.busy()||projectData().isEmpty())return;auto dialog=new QDialog(this);dialog->setAttribute(Qt::WA_DeleteOnClose);dialog->setObjectName("assuranceDialog");dialog->setWindowTitle(tr("제작 시험 · 상태 / 실패 / 저장 검증"));dialog->resize(1100,740);auto box=new QVBoxLayout(dialog);auto bar=new QHBoxLayout;auto runs=new QSpinBox;runs->setObjectName("assuranceRuns");runs->setRange(1,128);runs->setValue(32);auto start=new QPushButton(tr("검증 시작"));start->setObjectName("assuranceStart");bar->addWidget(new QLabel(tr("무작위 회차")));bar->addWidget(runs);bar->addWidget(start);bar->addStretch();box->addLayout(bar);auto summary=new QLabel(tr("명령/대상 후보와 거부 사유, 상태 범위, 버전 충돌, 관측한 진행 세션 취소, 중간 저장·재생 일치를 검사합니다. 미관측 경로는 미검증입니다."));summary->setObjectName("assuranceSummary");summary->setWordWrap(true);box->addWidget(summary);auto table=new QTableWidget(0,4);table->setObjectName("assuranceCoverage");table->setHorizontalHeaderLabels({tr("명령 묶음"),tr("실행 가능"),tr("거부"),tr("거부 사유")});table->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);box->addWidget(table);auto details=new QPlainTextEdit;details->setObjectName("assuranceDetails");details->setReadOnly(true);details->setMaximumHeight(230);box->addWidget(details);const auto root=view.value("root"),revision=view.value("revision");
 connect(start,&QPushButton::clicked,dialog,[=,this]{if(bridge.busy())return;if(root!=view.value("root")||revision!=view.value("revision")){summary->setText(tr("프로젝트 초안이 변경되었습니다. 창을 다시 여세요."));return;}start->setEnabled(false);summary->setText(tr("검증 중 · 결과는 프로젝트 .studio/assurance에 보존합니다."));QPointer<QDialog> guard(dialog);request("assuranceRun",{{"revision",revision},{"runs",runs->value()},{"seed",42}},[=](QJsonObject reply){if(!guard)return;start->setEnabled(true);const auto report=reply.value("assurance").toObject();if(report.isEmpty()){summary->setText(tr("검증 실패: ")+QJsonDocument(reply).toJson(QJsonDocument::Compact));return;}const auto result=report.value("result").toObject(),checks=report.value("checks").toObject();summary->setText(tr("%1 · %2/%3회 · 상태 전이 %4 · 저장 복원 %5 · 버전 충돌 거부 %6 · 세션 취소 %7\n%8").arg(report.value("ok").toBool()?tr("검사 통과"):tr("오류 또는 미완료")).arg(result.value("completed").toInt()).arg(result.value("requested").toInt()).arg(checks.value("transitions").toInt()).arg(checks.value("saves").toInt()).arg(checks.value("rejections").toInt()).arg(checks.value("cancellations").toInt()).arg(report.value("file").toString()));table->setRowCount(0);const auto coverage=report.value("coverage").toObject();for(auto it=coverage.begin();it!=coverage.end();++it){auto c=it.value().toObject();int row=table->rowCount();table->insertRow(row);QStringList values{it.key(),QString::number(c.value("available").toInt()),QString::number(c.value("blocked").toInt()),QString::fromUtf8(QJsonDocument(c.value("reasons").toObject()).toJson(QJsonDocument::Compact))};for(int col=0;col<4;++col)table->setItem(row,col,new QTableWidgetItem(values[col]));}details->setPlainText(QString::fromUtf8(QJsonDocument(QJsonObject{{"결과",result.value("outcomes")},{"도달한 엔딩",result.value("endings")},{"실패 위치와 원인",report.value("failures")},{"거부한 대상과 사유",report.value("blockedExamples")},{"검증 한계",report.value("limitations")}}).toJson()));});});dialog->show();
}
